CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, username text UNIQUE, password_hash text, nickname text NOT NULL DEFAULT '野生小猪', avatar_id uuid, phone_cipher text, phone_hash text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE identities(provider text NOT NULL, subject text NOT NULL,user_id uuid NOT NULL REFERENCES users(id),PRIMARY KEY(provider,subject));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE families(id uuid PRIMARY KEY,name text NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE members(family_id uuid REFERENCES families(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN('cook','eater')),identity text NOT NULL DEFAULT '野生小猪',joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(family_id,user_id));
CREATE TABLE collections(id uuid PRIMARY KEY,family_id uuid NOT NULL REFERENCES families(id),name text NOT NULL,sort_order integer NOT NULL DEFAULT 0,UNIQUE(family_id,name));
CREATE TABLE dishes(id uuid PRIMARY KEY,family_id uuid NOT NULL REFERENCES families(id),collection_id uuid NOT NULL REFERENCES collections(id),name text NOT NULL,intro text NOT NULL DEFAULT '',cover_id uuid,minutes integer NOT NULL DEFAULT 15,servings integer NOT NULL DEFAULT 2,sort_order integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,archived boolean NOT NULL DEFAULT false);
CREATE TABLE recipes(dish_id uuid PRIMARY KEY REFERENCES dishes(id),ingredients jsonb NOT NULL,steps jsonb NOT NULL);
CREATE TABLE inventories(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),family_id uuid REFERENCES families(id),name text NOT NULL,quantity numeric NOT NULL CHECK(quantity>=0),unit text NOT NULL,category text NOT NULL DEFAULT '其他',version integer NOT NULL DEFAULT 1,CHECK((user_id IS NULL)<>(family_id IS NULL)));
CREATE UNIQUE INDEX inventory_user ON inventories(user_id,name,unit) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX inventory_family ON inventories(family_id,name,unit) WHERE family_id IS NOT NULL;
CREATE TABLE invitations(token_hash text PRIMARY KEY,family_id uuid NOT NULL REFERENCES families(id),role text NOT NULL CHECK(role IN('cook','eater')),creator_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,consumed_by uuid REFERENCES users(id),revoked boolean NOT NULL DEFAULT false);
CREATE TABLE orders(id uuid PRIMARY KEY,family_id uuid NOT NULL REFERENCES families(id),user_id uuid NOT NULL REFERENCES users(id),meal_date date NOT NULL,slot text NOT NULL CHECK(slot IN('早餐','午餐','晚餐')),status text NOT NULL CHECK(status IN('pending','accepted','rejected','cancelled')),note text NOT NULL DEFAULT '',reply text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE order_lines(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),dish_id uuid NOT NULL REFERENCES dishes(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),snapshot jsonb NOT NULL,done boolean NOT NULL DEFAULT false);
CREATE TABLE prep_checks(family_id uuid REFERENCES families(id),meal_date date NOT NULL,name text NOT NULL,unit text NOT NULL,checked boolean NOT NULL,PRIMARY KEY(family_id,meal_date,name,unit));
CREATE TABLE changes(id uuid PRIMARY KEY,line_id uuid NOT NULL REFERENCES order_lines(id),user_id uuid NOT NULL REFERENCES users(id),replacement_id uuid NOT NULL REFERENCES dishes(id),line_version integer NOT NULL,status text NOT NULL CHECK(status IN('pending','accepted','rejected','cancelled','obsolete')),reason text NOT NULL DEFAULT '',reply text NOT NULL DEFAULT '',old_snapshot jsonb NOT NULL,new_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX pending_change ON changes(line_id) WHERE status='pending';
CREATE TABLE shares(id uuid PRIMARY KEY,token_hash text UNIQUE NOT NULL,source_family_id uuid NOT NULL REFERENCES families(id),sender_id uuid NOT NULL REFERENCES users(id),snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE import_receipts(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),family_id uuid NOT NULL REFERENCES families(id),share_id uuid NOT NULL REFERENCES shares(id),mode text NOT NULL,scope text NOT NULL,added integer NOT NULL,replaced integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dissolutions(id uuid PRIMARY KEY,family_id uuid NOT NULL REFERENCES families(id),initiator uuid NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN('pending','rejected','completed','cancelled','invalidated')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX pending_dissolution ON dissolutions(family_id) WHERE status='pending';
CREATE TABLE votes(proposal_id uuid REFERENCES dissolutions(id),user_id uuid REFERENCES users(id),decision text CHECK(decision IN('agree','reject')),PRIMARY KEY(proposal_id,user_id));
CREATE TABLE notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),family_id uuid REFERENCES families(id),type text NOT NULL,entity_id uuid,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),family_id uuid REFERENCES families(id),action text NOT NULL,entity_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(user_id uuid REFERENCES users(id),key text NOT NULL,operation text NOT NULL,request_hash text NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE media(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),filename text NOT NULL,mime text NOT NULL,size integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sms_challenges(phone_hash text PRIMARY KEY,code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,sent_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_family_date ON orders(family_id,meal_date,status);
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX membership_user ON members(user_id,family_id);
CREATE INDEX dishes_family ON dishes(family_id,archived,sort_order);

CREATE TABLE sms_limits(kind text NOT NULL,subject text NOT NULL,day date NOT NULL,count integer NOT NULL,PRIMARY KEY(kind,subject,day));
